/**
 * The `kiro-cli` shim KiroCrew runs as `KIROCREW_KIRO_BIN` (08-kirocrew-integration §0 item 2,
 * §2.1, §3.4 — content exact and byte-stable):
 *
 * ```sh
 * #!/bin/sh
 * # Generated by `kiro-claude crew setup`. Do not edit; rerun setup instead.
 * # Kiro Crew runs this file as its kiro-cli (KIROCREW_KIRO_BIN). Its probes use a
 * # minimal environment, so the node and Claude Code paths are fixed here.
 * KIRO_CLAUDE_BIN="${KIRO_CLAUDE_BIN:-/opt/claude-code/bin/claude}"
 * export KIRO_CLAUDE_BIN
 * exec '/opt/node22/bin/node' '/home/u/KIRO-Claude/dist/src/bin/kiro-claude.js' "$@"
 * ```
 *
 * - Named `kiro-claude`, never `kiro-cli` (V4: KiroCrew's doctor then looks for a `kiro-cli-chat`
 *   sibling and reports "Kiro CLI is broken"), and never under a probe-hidden dir (KC-BIN-02).
 * - `node` and the JS entry are absolute and single-quoted (`'` → `'\''`); the probe environment
 *   is an allowlist that drops `KIRO_CLAUDE_BIN` and may lack `node` on PATH (KC-BIN-03).
 * - `$KIRO_CLAUDE_BIN` from the environment still wins (ACP spawns inherit the gateway env).
 * - KiroCrew records the shim's sha256 at process start and caches help output by mtime
 *   (KC-BIN-04, V15), so the file is only rewritten when its bytes change.
 *
 * DECISION (ours): a Claude path containing a character that is special inside a double-quoted
 * `${VAR:-word}` (`$`, `` ` ``, `"`, `\`, `}`) cannot be written in the §3.4 form safely; neither can
 * one with a `'` (bash outside POSIX mode, e.g. `bash <shim>`, then looks for a closing quote and
 * fails). Such paths use an equivalent `if` form with a single-quoted value instead. Ordinary
 * paths always produce the exact §3.4 bytes.
 */
import * as fs from 'node:fs';
import * as path from 'node:path';

import { writeFileAtomic } from '../util/fsx.js';

export interface ShimSpec {
  /** Absolute node executable (`process.execPath` of the kiro-claude that ran setup). */
  node: string;
  /** Absolute kiro-claude JS entry (`…/dist/src/bin/kiro-claude.js`). */
  entry: string;
  /** Absolute Claude Code executable baked in as the `KIRO_CLAUDE_BIN` default. */
  claude: string;
}

/** Basenames KiroCrew treats specially; the shim must not use them (KC-BIN-01). */
export const FORBIDDEN_SHIM_NAMES: readonly string[] = Object.freeze(['kiro-cli', 'kiro-cli-chat']);

/** POSIX single-quoting: `'a'\''b'`. */
export function shSingleQuote(s: string): string {
  return `'${s.replace(/'/g, `'\\''`)}'`;
}

const UNSAFE_IN_DQ_DEFAULT = /[$`"\\}']/;

function assertUsablePath(label: string, p: string): void {
  if (!p) throw new Error(`shim: ${label} path is empty`);
  if (!path.isAbsolute(p)) throw new Error(`shim: ${label} path must be absolute (got ${p})`);
  if (/[\0\n\r]/.test(p)) throw new Error(`shim: ${label} path contains a newline or NUL character`);
}

/** Renders the shim text (§3.4). Throws on relative paths or paths with newlines. */
export function renderShim(spec: ShimSpec): string {
  assertUsablePath('node', spec.node);
  assertUsablePath('entry', spec.entry);
  assertUsablePath('Claude Code', spec.claude);
  const header =
    '#!/bin/sh\n' +
    '# Generated by `kiro-claude crew setup`. Do not edit; rerun setup instead.\n' +
    '# Kiro Crew runs this file as its kiro-cli (KIROCREW_KIRO_BIN). Its probes use a\n' +
    '# minimal environment, so the node and Claude Code paths are fixed here.\n';
  const binLine = UNSAFE_IN_DQ_DEFAULT.test(spec.claude)
    ? `if [ -z "\${KIRO_CLAUDE_BIN:-}" ]; then KIRO_CLAUDE_BIN=${shSingleQuote(spec.claude)}; fi\n`
    : `KIRO_CLAUDE_BIN="\${KIRO_CLAUDE_BIN:-${spec.claude}}"\n`;
  return (
    header +
    binLine +
    'export KIRO_CLAUDE_BIN\n' +
    `exec ${shSingleQuote(spec.node)} ${shSingleQuote(spec.entry)} "$@"\n`
  );
}

export interface ShimWriteResult {
  path: string;
  /** False when the file already had exactly these bytes and mode (nothing was touched). */
  changed: boolean;
}

/**
 * Writes the shim atomically with mode 0755. A file with identical bytes is left alone (its
 * mtime/inode stay, so KiroCrew's help cache and recorded digest stay valid); only a wrong mode
 * is repaired in place.
 */
export function writeShim(file: string, spec: ShimSpec): ShimWriteResult {
  const text = renderShim(spec);
  const base = path.basename(file);
  if (FORBIDDEN_SHIM_NAMES.includes(base)) throw new Error(`shim: refusing to name the shim ${base} (KiroCrew treats that name as the real Kiro CLI)`);
  let current: string | undefined;
  try {
    current = fs.readFileSync(file, 'utf8');
  } catch {
    current = undefined;
  }
  if (current === text) {
    try {
      const mode = fs.statSync(file).mode & 0o777;
      if (mode !== 0o755) fs.chmodSync(file, 0o755);
    } catch {
      // ignore
    }
    return { path: file, changed: false };
  }
  writeFileAtomic(file, text, { mode: 0o755 });
  return { path: file, changed: true };
}

/** The second line of every shim this module writes (how `crew uninstall` recognises ours). */
export const SHIM_MARKER = '# Generated by `kiro-claude crew setup`. Do not edit; rerun setup instead.';

/** True when `file` is a regular file written by {@link writeShim} (header check; never follows a symlink). */
export function isGeneratedShim(file: string): boolean {
  try {
    const st = fs.lstatSync(file);
    if (!st.isFile() || st.size > 64 * 1024) return false;
    const head = fs.readFileSync(file, 'utf8').split('\n', 2);
    return head[0] === '#!/bin/sh' && head[1] === SHIM_MARKER;
  } catch {
    return false;
  }
}

export interface ShimCheck {
  ok: boolean;
  problems: string[];
}

/** Static shim checks for doctor D6 (KC-BIN-01, content equality with the regenerated text). */
export function checkShim(file: string, spec: ShimSpec | undefined): ShimCheck {
  const problems: string[] = [];
  const base = path.basename(file);
  if (FORBIDDEN_SHIM_NAMES.includes(base)) problems.push(`basename is ${base}`);
  if (!path.isAbsolute(file)) problems.push('path is not absolute');
  let st: fs.Stats | undefined;
  try {
    st = fs.statSync(file);
  } catch {
    problems.push(`${file} does not exist`);
    return { ok: false, problems };
  }
  if (!st.isFile()) problems.push(`${file} is not a file`);
  else if (st.size === 0) problems.push(`${file} is empty`);
  if (process.platform !== 'win32' && (st.mode & 0o111) === 0) problems.push(`${file} is not executable`);
  if (spec) {
    let expected: string | undefined;
    try {
      expected = renderShim(spec);
    } catch (e) {
      problems.push((e as Error).message);
    }
    if (expected !== undefined) {
      let current = '';
      try {
        current = fs.readFileSync(file, 'utf8');
      } catch {
        current = '';
      }
      if (current !== expected) problems.push('content differs from what setup would write (stale node/entry/claude path)');
    }
  }
  return { ok: problems.length === 0, problems };
}
